# owner: platform
"""Lay students out in rows for a seating chart."""

from typing import Iterable, List

from rosterkit.models import Student

# ---
def _last_name_key(student: Student) -> str:
    return student.last_name.casefold()

# ---
def _ordered(students: Iterable[Student]) -> List[Student]:
    ordered = sorted(students, key=_last_name_key)
    if not ordered:
        raise ValueError("no students to seat")
    return ordered

# ---
def _row_text(number: int, group: List[Student]) -> str:
    names = [student.display_name for student in group]
    return f"Row {number}: " + " | ".join(names)

# ---
def _rows(ordered: List[Student], seats: int) -> List[str]:
    lines = []
    for start in range(0, len(ordered), seats):
        group = ordered[start : start + seats]
        lines.append(_row_text(start // seats + 1, group))
    return lines

# ---
def seating_rows(
    students: Iterable[Student], per_row: int
) -> List[str]:
    """One line per row, students in last name order."""
    if per_row <= 0:
        raise ValueError("seats per row must be positive")
    return _rows(_ordered(students), per_row)
